//! End-to-end checks on small synthetic PDFs (tests/fixtures, generated by
//! bench/generate_corpus.py; no real data). They run on every platform in
//! CI and need PDFium: the embedded copy, or $PDFIUM_LIB_DIR.

use std::path::{Path, PathBuf};

use pdfium_render::prelude::Pdfium;

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name)
}

/// PDFium binds once per process, so every test shares one instance.
fn pdfium() -> &'static Pdfium {
    static PDFIUM: std::sync::OnceLock<Pdfium> = std::sync::OnceLock::new();
    PDFIUM.get_or_init(|| {
        let dir = std::env::var_os("PDFIUM_LIB_DIR").map(PathBuf::from);
        pagelens::backend::bind_default(dir.as_deref()).expect("PDFium (embedded or $PDFIUM_LIB_DIR)")
    })
}

fn parse(pdfium: &Pdfium, name: &str) -> pagelens::DocResult {
    let pages = pagelens::backend::load_pages(pdfium, &fixture(name)).expect("readable PDF");
    pagelens::analyse(&pages)
}

#[test]
fn invoice_table_and_no_false_pii() {
    let pdfium = pdfium();
    let doc = parse(pdfium, "invoice_1.pdf");
    assert_eq!(doc.tables.len(), 1, "one line-item table");
    assert_eq!(doc.tables[0][0], vec!["Description", "Qty", "Unit price", "Amount"]);
    assert_eq!(doc.tables[0].len(), 7, "header and six items");
    assert!(doc.markdown.contains("| Description | Qty | Unit price | Amount |"));
    // Invoice and due dates are not phone numbers.
    assert!(doc.pii.iter().all(|p| p.kind != "phone"), "{:?}", doc.pii.iter().map(|p| &p.text).collect::<Vec<_>>());
}

#[test]
fn bordered_and_borderless_tables() {
    let pdfium = pdfium();
    for name in ["table_bordered_1.pdf", "table_borderless_1.pdf"] {
        let doc = parse(pdfium, name);
        assert!(!doc.tables.is_empty(), "{name}: no table found");
        let cols = doc.tables[0][0].len();
        assert!(cols >= 3, "{name}: {cols} columns");
        assert!(doc.tables[0].iter().all(|r| r.len() == cols), "{name}: ragged rows");
    }
}

#[test]
fn two_columns_read_in_order() {
    let pdfium = pdfium();
    let doc = parse(pdfium, "two_column_paper_1.pdf");
    let truth: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(fixture("two_column_paper_1.json")).expect("ground truth"),
    )
    .unwrap();
    // Every ground-truth line appears, and in the right order.
    let text = doc.text.replace('\n', " ");
    let mut at = 0;
    for line in truth["lines"].as_array().unwrap() {
        let line = line.as_str().unwrap();
        let found = text[at..].find(line).unwrap_or_else(|| panic!("missing or out of order: {line}"));
        at += found + line.len();
    }
}

#[test]
fn writer_round_trip() {
    let pdfium = pdfium();
    let doc = parse(pdfium, "invoice_1.pdf");
    let out = std::env::temp_dir().join(format!("pagelens-test-{}.pdf", std::process::id()));
    let opts = pagelens::render::RenderOptions { logo: None, redact: true, candidate_label: None, header_note: None, remove: false };
    pagelens::render::write_pdf(pdfium, &doc, &out, &opts).expect("PDF written");
    let again = pagelens::backend::load_pages(pdfium, &out).expect("output readable");
    let text = pagelens::analyse(&again).text;
    let _ = std::fs::remove_file(&out);
    assert!(text.contains("Total"), "{text}");
    assert!(text.contains("147,106.00"), "{text}");
}

fn structured(name: &str) -> pagelens::DocResult {
    let pages = pagelens::structured::load(&fixture(name)).expect("readable file");
    pagelens::structured::analyse_blocks(pages)
}

#[test]
fn docx_structure_tables_and_pii() {
    let doc = structured("resume.docx");
    let md = &doc.markdown;
    assert!(md.starts_with("# Asha Example"), "{md}");
    assert!(md.contains("# Experience") && md.contains("## Skills"), "{md}");
    assert!(md.contains("- Led a team of four engineers"), "{md}");
    assert_eq!(doc.tables, vec![vec![
        vec!["Skill".to_string(), "Years".into(), "Level".into()],
        vec!["Rust".into(), "4".into(), "Expert".into()],
        vec!["SQL".into(), "6".into(), "Advanced".into()],
    ]]);
    let kinds: Vec<&str> = doc.pii.iter().map(|p| p.kind).collect();
    assert!(kinds.contains(&"email") && kinds.contains(&"phone") && kinds.contains(&"person_name"), "{kinds:?}");
    let redacted = pagelens::redact_doc(doc);
    let json = serde_json::to_string(&redacted).unwrap();
    for raw in ["asha@example.com", "98765 43210", "Asha Example"] {
        assert!(!json.contains(raw), "redacted output leaks {raw}");
    }
}

#[test]
fn pptx_slides_in_order() {
    let doc = structured("deck.pptx");
    assert_eq!(doc.pages.len(), 3);
    assert!(doc.pages[0].markdown.starts_with("# Quarterly Review"));
    assert!(doc.pages[1].markdown.contains("- Revenue up 12 percent"));
    assert_eq!(doc.tables.len(), 1);
    assert_eq!(doc.tables[0][1], vec!["North", "120", "140"]);
    // A deck title is not a person's name.
    assert!(doc.pii.is_empty(), "{:?}", doc.pii.iter().map(|p| &p.text).collect::<Vec<_>>());
}

#[test]
fn html_skips_hidden_content() {
    let doc = structured("page.html");
    assert!(doc.markdown.starts_with("# Asha Example"));
    assert!(doc.markdown.contains("- Python & SQL"));
    assert!(!doc.markdown.contains("keyword stuffing") && !doc.markdown.contains("var x"));
    assert_eq!(doc.tables[0], vec![vec!["Year".to_string(), "Role".into()], vec!["2024".into(), "Engineer".into()]]);
}

#[test]
fn branded_profile_from_docx() {
    let doc = structured("resume.docx");
    let profile = pagelens::profile::build(&doc, "Candidate #7", false);
    assert!(!profile.experience.is_empty(), "{profile:?}");
    assert!(!profile.skills.is_empty() || !profile.extras.is_empty(), "{profile:?}");
    let json = serde_json::to_string(&profile).unwrap();
    for raw in ["asha@example.com", "98765 43210", "Asha Example", "[EMAIL]", "[PHONE]"] {
        assert!(!json.contains(raw), "profile leaks {raw}");
    }

    let dir = std::env::temp_dir().join(format!("pagelens-brand-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let theme_path = dir.join("theme.json");
    std::fs::write(&theme_path, r##"{"agency": "Acme Talent", "color": "#1F4E8C"}"##).unwrap();
    let theme = pagelens::brand::Theme::load(&theme_path).unwrap();
    let branding = pagelens::brand::Branding {
        theme: &theme,
        label: "Candidate #7".into(),
        notes: vec![("Notice period".into(), "30 days".into())],
    };
    let out = dir.join("out.pdf");
    let pdfium = pdfium();
    let pages = pagelens::brand::write_branded(pdfium, &profile, &out, &branding).expect("branded PDF");
    assert!(pages >= 1);
    let text = pagelens::analyse(&pagelens::backend::load_pages(pdfium, &out).unwrap()).text;
    let _ = std::fs::remove_dir_all(&dir);
    assert!(text.contains("Candidate #7") && text.contains("Acme Talent") && text.contains("30 days"), "{text}");
    assert!(!text.contains("asha@example.com"));
}

/// Analyse an HTML string (a stand-in for any resume layout).
fn html(name: &str, body: &str) -> pagelens::DocResult {
    let dir = std::env::temp_dir().join(format!("pagelens-html-{}-{name}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join(format!("{name}.html"));
    std::fs::write(&path, format!("<html><body>{body}</body></html>")).unwrap();
    let doc = pagelens::structured::load(&path).map(pagelens::structured::analyse_blocks).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    doc
}

const BODY: &str = "<h2>Experience</h2><p>Led a platform team of 6 at Northwind (2019 - Present).</p>\
    <h2>Education</h2><p>B.E. Computer Science, 2015</p><h2>Skills</h2><p>Rust, Python, GitHub Actions</p>";

#[test]
fn names_at_the_top_in_any_layout() {
    let cases = [
        ("caps", "<h1>RAVI KUMAR</h1><p>ravi.k@mail.example</p>"),
        ("pipes", "<p>Ravi Kumar | Pune, India | +91 98765 43210</p>"),
        ("split", "<h1>RAVI</h1><h1>KUMAR</h1><p>Lead engineer</p><p>ravikumar@mail.example</p>"),
    ];
    for (name, top) in cases {
        let doc = html(name, &format!("{top}{BODY}<p>Contact Ravi on github.com/ravi-kumar</p>"));
        let red = pagelens::redact_doc(doc).text;
        assert!(!red.contains("Ravi") && !red.contains("RAVI") && !red.contains("Kumar") && !red.contains("KUMAR"), "{name}: {red}");
        assert!(red.contains("GitHub Actions") && red.contains("Northwind"), "{name}: over-redacted: {red}");
    }
}

#[test]
fn known_details_are_removed_everywhere() {
    pagelens::pii::set_known(Some(pagelens::pii::Known {
        name: Some("Meera Iyer".into()),
        phone: Some("+91 99887 76655".into()),
        email: None,
        other: vec!["42 Lake Road".into()],
    }));
    let doc = html("known", &format!("<p>M. IYER</p><p>Call 99887-76655</p>{BODY}<p>Lives at 42 Lake Road. Meera led it.</p>"));
    pagelens::pii::set_known(None);
    let red = pagelens::redact_doc(doc).text;
    for raw in ["IYER", "Meera", "76655", "Lake Road"] {
        assert!(!red.contains(raw), "{raw} left in {red}");
    }
}

#[test]
fn output_check_and_hidden_employer() {
    let doc = html("check", &format!("<h1>RAVI KUMAR</h1><p>ravi.k@mail.example</p>{BODY}"));
    let mut profile = pagelens::profile::build(&doc, "Candidate #9", false);
    assert_eq!(profile.hide_current_employer("Confidential"), vec!["Northwind".to_string()], "{profile:?}");
    let json = serde_json::to_string(&profile).unwrap();
    assert!(!json.contains("Northwind") && json.contains("Confidential"), "{json}");
    // The check catches what is left and allows the agency's own text.
    assert!(pagelens::check::leaks(&doc, "Candidate #9\nRust", &["Candidate #9".into()], None).is_empty());
    assert!(!pagelens::check::leaks(&doc, "Candidate #9\nRAVI led", &[], None).is_empty());
    assert!(!pagelens::check::leaks(&doc, "mail ravi.k@mail.example", &[], None).is_empty());
}

/// Page-level layout found on real resumes (fixture generated by
/// bench/make_layout_fixtures.py, invented content): section headings in
/// body type, bullets drawn as shapes, a numbered list, a table whose header
/// sits above its first rule and which continues on page 2, a running head
/// and page numbers.
#[test]
fn multipage_resume_layout() {
    let pdfium = pdfium();
    let doc = parse(pdfium, "multipage_resume.pdf");
    let md = &doc.markdown;
    for h in ["## Experience", "## Key projects", "## Education", "## Skills"] {
        assert!(md.contains(h), "section heading in body type: {h}\n{md}");
    }
    assert!(md.contains("- Built a streaming pipeline for order events\n"), "dot bullet drawn as a shape\n{md}");
    assert!(md.contains("- Moved reporting jobs to a shared scheduler"), "square bullet drawn as a shape\n{md}");
    assert!(md.contains("1. Customer churn model") && md.contains("2. Data quality checks"), "numbered list\n{md}");
    assert!(md.contains("| Course | Institute | Year |"), "header row above the first rule is in the table\n{md}");
    assert!(md.contains("| Cloud Data Certificate | Online Academy | 2020 |"), "table continued on page 2 is joined\n{md}");
    assert_eq!(md.matches("| Course |").count(), 1, "repeated header row dropped\n{md}");
    assert!(!md.contains("\n---\n"), "no rule at the page break\n{md}");
    assert!(!md.contains("Page 1 of 2") && !md.contains("Page 2 of 2"), "page numbers dropped\n{md}");
    assert_eq!(md.matches("alex.example@example.com").count(), 1, "running head kept once\n{md}");
    assert!(doc.text.contains("Page 2 of 2"), "the raw text keeps the furniture");
    assert!(md.contains("- English, fluent") && md.contains("- Spanish, working knowledge"), "bullets drawn by one path\n{md}");
    assert!(md.contains("## Project Description"), "section heading right under an unfinished bullet\n{md}");
}

/// Wrapped bullets at 1.5 line spacing stay one item each, with character
/// and with drawn bullets; separate paragraphs stay separate.
#[test]
fn wrapped_bullets_at_wide_line_spacing() {
    let pdfium = pdfium();
    let md = parse(pdfium, "spaced_bullets.pdf").markdown;
    let item = "Owned the order events pipeline end to end, from the Kafka topics through the warehouse loaders to the finance dashboards";
    assert_eq!(md.matches(item).count(), 2, "both wrapped items whole (character and drawn bullet)\n{md}");
    assert_eq!(md.matches("- Reviewed every schema change").count(), 2, "items stay apart\n{md}");
    assert!(
        md.contains("\n\nThe team moved to a new scheduler in the spring.\n\nA second paragraph"),
        "paragraphs stay apart\n{md}"
    );
}

/// In a resume, short labels set over a picture (skill badges, a panel
/// exported as an image) are content and reach the Markdown.
#[test]
fn resume_text_over_an_image_is_kept() {
    let pdfium = pdfium();
    let md = parse(pdfium, "resume_image_badges.pdf").markdown;
    for skill in ["Python", "Airflow", "Terraform", "Kubernetes"] {
        assert!(md.contains(skill), "{skill} on the image panel\n{md}");
    }
    let skills = md.find("Skills").unwrap();
    let experience = md.find("Experience").unwrap();
    let python = md.find("Python").unwrap();
    assert!(skills < python && python < experience, "badges sit under Skills\n{md}");
}

/// Links whose text hides the address keep it as Markdown links; links whose
/// text is the address stay plain; an icon link's address is written out.
#[test]
fn hidden_link_targets_are_kept() {
    let pdfium = pdfium();
    let md = parse(pdfium, "resume_links.pdf").markdown;
    assert!(md.contains("[LinkedIn](https://www.linkedin.com/in/sam-sample-0000)"), "{md}");
    assert!(!md.contains("](mailto:"), "a visible address is not wrapped\n{md}");
    assert!(md.contains("<https://github.com/sample-dev-0000>"), "icon link\n{md}");
    assert!(md.contains("](https://orders.example.org/demo)"), "wrapped label\n{md}");
}

/// Bullets drawn inside an embedded drawing group (form XObject) placed
