/// A section name alone in a merged table row becomes a heading between two
/// tables.
#[test]
fn section_name_row_splits_a_table() {
    let pdfium = pdfium();
    let md = parse(pdfium, "section_in_table.pdf").markdown;
    assert!(md.lines().any(|l| l == "## Experience"), "{md}");
    assert!(!md.contains("| Experience |"), "{md}");
    let (edu, exp, job) = (md.find("Riverside College").unwrap(), md.find("## Experience").unwrap(), md.find("Fabrikam").unwrap());
    assert!(edu < exp && exp < job, "{md}");
}

/// The name's confidence rests on the email address: backed 0.95, nothing to
/// compare 0.75, contradicted 0.5; doubtful names are listed for review.
#[test]
fn name_confidence_follows_the_evidence() {
    let pdfium = pdfium();
    for (file, name, confidence, review) in [
        ("name_email_match.pdf", "Priya Raman", 0.95, false),
        ("name_no_email.pdf", "Arjun Mehta", 0.75, true),
        ("name_email_differs.pdf", "Kavya Iyer", 0.5, true),
        // The name on its own line inside a block with the line above it.
        ("name_second_line.pdf", "Rohan Deshpande", 0.75, true),
        // The line the email backs, not the name-shaped line above it.
        ("name_email_beats_shape.pdf", "Neha Kulkarni", 0.95, false),
    ] {
        let doc = parse(pdfium, file);
        let n = doc.person.name.as_ref().unwrap_or_else(|| panic!("{file}: no name"));
        assert_eq!(n.text, name, "{file}");
        assert_eq!(n.confidence, confidence, "{file}");
        assert_eq!(doc.needs_review.iter().any(|r| r.kind == "name"), review, "{file}");
        // A single well-formed phone number is not listed.
        assert!(!doc.needs_review.iter().any(|r| r.kind == "phone"), "{file}");
    }
}

/// Without OCR, a scanned page and a picture of printed text are listed for
/// an LLM to read, with a placeholder where their text belongs; a photo is
/// not listed.
#[cfg(not(feature = "ocr"))]
#[test]
fn unread_scans_and_text_images_are_listed() {
    let pdfium = pdfium();
    let doc = parse(pdfium, "resume_text_image.pdf");
    let images: Vec<_> = doc.needs_review.iter().filter(|r| r.kind == "image").collect();
    assert_eq!(images.len(), 1, "the certificate picture only, not the photo: {:?}", doc.needs_review);
    assert_eq!(images[0].action, "read_with_llm");
    let md = &doc.markdown;
    let (cert, mark, exp) = (md.find("Certifications").unwrap(), md.find("<!-- image not read").unwrap(), md.find("## Experience").unwrap());
    assert!(cert < mark && mark < exp, "placeholder where the picture is\n{md}");
    let doc = parse(pdfium, "scanned_page.pdf");
    assert!(doc.needs_review.iter().any(|r| r.kind == "scanned_page" && r.page == Some(1) && r.action == "read_with_llm"));
    assert!(doc.markdown.contains("<!-- scanned page not read"));
    // One line of text as a picture (a contact bar) is listed; a rating bar
    // and a divider of the same size are not.
    let doc = parse(pdfium, "resume_contact_strip.pdf");
    let images: Vec<_> = doc.needs_review.iter().filter(|r| r.kind == "image").collect();
    assert_eq!(images.len(), 1, "{:?}", doc.needs_review);
    assert!(images[0].bbox.is_some_and(|b| b.y0 < 110.0), "the contact line at the top: {:?}", images[0].bbox);
}

/// Email and phone come out whole and clean however the text layer wrote
/// them: words after a labelled value, a space inside the address, a number
/// after a link that ends in digits, a number wrapped onto the next line, a
/// mailto link over a piece of the address.
#[test]
fn contact_details_come_out_whole() {
    let pdfium = pdfium();
    let cases = [
        ("contact_label_words.pdf", Some("555-123-4567")),
        ("contact_spaced.pdf", Some("+1 555 123 4567")),
        ("contact_link_tail.pdf", Some("9876543210")),
        ("contact_wrapped_phone.pdf", Some("+1 (555) 123 4567")),
        ("contact_wrapped_number_label.pdf", Some("555- 123-4567")),
        ("contact_mailto_piece.pdf", None),
    ];
    // The address written out wins over an icon's hidden target.
    let doc = parse(pdfium, "contact_icon_other_mailbox.pdf");
    assert_eq!(doc.person.email.as_ref().map(|d| d.text.as_str()), Some("sam.sample@example.com"), "{}", doc.markdown);
    let doc = parse(pdfium, "contact_mailto_word_piece.pdf");
    assert!(doc.markdown.contains("[Email:](mailto:sam.sample@example.com)"), "a link over part of a word links the word\n{}", doc.markdown);
    assert_eq!(doc.person.email.as_ref().map(|d| d.text.as_str()), Some("sam.sample@example.com"));
    for (file, phone) in cases {
        let doc = parse(pdfium, file);
        let email = doc.person.email.as_ref().map(|d| d.text.as_str());
        assert_eq!(email, Some("sam.sample@example.com"), "{file}\n{}", doc.markdown);
        assert_eq!(doc.person.phone.as_ref().map(|d| d.text.as_str()), phone, "{file}\n{}", doc.markdown);
        assert!(!doc.markdown.contains("](mailto:"), "no link inside the address: {file}\n{}", doc.markdown);
        assert!(doc.needs_review.iter().all(|r| r.kind != "email" && r.kind != "phone"), "{file}");
        let redacted = &doc.markdown_redacted;
        assert!(!redacted.contains("sam.sample") && !redacted.contains("4567") && !redacted.contains("3210"), "{file}\n{redacted}");
    }
}

/// The street and PIN of an address, a UPI ID and the referees are removed;
/// the city stays for the reader (and the LLM) to see.
#[test]
fn addresses_upi_and_referees_are_personal_data() {
    let doc = parse(pdfium(), "personal_details.pdf");
    let red = &doc.markdown_redacted;
    for gone in ["3rd Cross", "560038", "samsample@okhdfc", "Anil Mehta", "Priya Nair"] {
        assert!(!red.contains(gone), "{gone} left in\n{red}");
    }
    assert!(red.contains("Bengaluru") && red.contains("Pune") && red.contains("Fabrikam"), "{red}");
    assert!(doc.markdown.contains("Anil Mehta"), "the original Markdown keeps the text");
}

/// A job header in bold body type (company, dates, title) after the last
/// bullet of the job above is a heading, so each job starts visibly.
#[test]
fn bold_job_headers_are_headings() {
    let pdfium = pdfium();
    let md = parse(pdfium, "job_headers.pdf").markdown;
    for company in ["Fabrikam Systems", "Contoso Retail", "Northwind Traders"] {
        assert!(md.lines().any(|l| l.starts_with('#') && l.contains(company)), "{company} heads its job\n{md}");
    }
    assert!(md.lines().filter(|l| l.starts_with("- ")).count() == 6, "{md}");
}

/// Dates set to the right of each job's company line are read with that
/// job, not as a column after all the jobs, and a range whose end wrapped
/// to the next line is one range.
#[test]
fn dates_beside_a_job_stay_with_it() {
    let pdfium = pdfium();
    let md = parse(pdfium, "job_dates_right.pdf").markdown;
    let at = |t: &str| md.find(t).unwrap_or_else(|| panic!("{t} missing\n{md}"));
    for (company, range, next) in [
        ("Fabrikam Systems", "Apr 2020 - Jun 2022", "Contoso Retail"),
        ("Contoso Retail", "Feb 2018 - Mar 2020", "Northwind Traders"),
    ] {
        assert!(at(company) < at(range) && at(range) < at(next), "{range} with {company}\n{md}");
    }
    assert!(at("Lead role at") < at("Northwind Traders") && at("Northwind Traders") < at("Jul 2014 - Jan 2018"), "{md}");
}

